UPDATE TemplatesConfig SET emails = '{"waitingList":{"subject":"Wartelistenplatz: {EVENT_TITLE}","bodyHtml":"\\n        <h3>Hallo {BOOKING_NAME},</h3>\\n        <p>vielen Dank für Ihr Interesse an <strong>{EVENT_TITLE}</strong>.</p>\\n        <p>Da die Veranstaltung derzeit ausgebucht ist, haben wir Sie auf die Warteliste gesetzt.</p>\\n        <p>Sobald ein Platz frei wird, werden wir Sie umgehend informieren.</p>\\n        <br/>\\n        <p>Mit freundlichen Grüßen,<br/>Ihr Team der Flugschule Hirondelle</p>\\n      "},"bookingConfirmation":{"subject":"Buchungsbestätigung: {EVENT_TITLE}","bodyHtml":"\\n          <h3>Hallo {BOOKING_NAME},</h3>\\n          <p>vielen Dank für Ihre Buchung.</p>\\n          <br/>\\n          {EVENT_DETAILS}\\n          <br/>\\n          {BOOKING_DETAILS}\\n          <br/>\\n          <p>Im Anhang finden Sie Ihre Rechnung und Ihr Ticket.</p>\\n          <hr/>\\n          <p>Die Kursgebühr wird 4 Wochen vor Kursbeginn fällig. Bei Kurzfristbuchungen (ab vier Wochen vor Kursbeginn) wird der gesamte Kurspreis sofort fällig.</p>\\n          <p>Wir führen eine echte Warteliste (der Kurs ist dann tatsächlich ausgebucht). Buchungen auf Warteliste sind daher erst zu bezahlen, wenn die Teilnahme auch sicher - und der Platz verbindlich bestätigt ist.</p>\\n          <p><strong>Bankverbindung</strong><br/>\\n          Kontoinhaber: Alexander Schlink<br/>\\n          Sparkasse Südpfalz<br/>\\n          IBAN: DE32 5485 0010 1700 1976 41<br/>\\n          BIC: SOLADES1SUW</p>\\n          <hr/>\\n          <p style=\\"color: #ff0000;\\">Wir empfehlen zur Absicherung für Stornos / Absagen den Abschluss einer Seminarversicherung bzw. für unsere mehrtätigen Kurse / Reisen zusätzlich eine Reiseversicherung. Infos dazu findet ihr auf unserer Seite <a href=\\"https://www.fs-hirondelle.de/infos/versicherungen\\" style=\\"color: #ff0000;\\">https://www.fs-hirondelle.de/infos/versicherungen</a>.</p>\\n          <hr/>\\n          <p>Mit freundlichen Grüßen,<br/>Ihr Team der Flugschule Hirondelle</p>\\n        "},"newEvent":{"subject":"Neue Veranstaltung: {EVENT_TITLE}","bodyHtml":"\\n          <h3>Hallo {USER_NAME},</h3>\\n          <p>es gibt eine neue Veranstaltung bei der Flugschule Hirondelle:</p>\\n          <br/>\\n          {EVENT_DETAILS}\\n          <br/>\\n          <p>Mit freundlichen Grüßen,<br/>Ihr Team der Flugschule Hirondelle</p>\\n        "},"freePlacesReminder":{"subject":"Noch freie Plätze: {EVENT_TITLE}","bodyHtml":"\\n          <h3>Hallo {USER_NAME},</h3>\\n          <p>für folgende Veranstaltung sind noch Plätze frei:</p>\\n          <br/>\\n          {EVENT_DETAILS}\\n          <br/>\\n          <p>Mit freundlichen Grüßen,<br/>Ihr Team der Flugschule Hirondelle</p>\\n        "},"userCancellation":{"subject":"Stornierungsbestätigung: {EVENT_TITLE}","bodyHtml":"<h3>Hallo {BOOKING_NAME},</h3><p>Sie haben Ihre Buchung storniert - Ihr Platz wurde freigegeben.</p><p>{EVENT_DETAILS}</p><br/><p>Mit freundlichen Grüßen,<br/>Ihr Team der Flugschule Hirondelle</p>","bodyText":"Hallo {BOOKING_NAME}, Sie haben Ihre Buchung storniert - Ihr Platz wurde freigegeben. {EVENT_DETAILS}"},"adminCancellation":{"subject":"Stornierung Ihrer Buchung: {EVENT_TITLE}","bodyHtml":"<h3>Hallo {BOOKING_NAME},</h3><p>Ihre Buchung für <strong>{EVENT_TITLE}</strong> wurde storniert. Ihre Buchung ist daher nicht mehr gültig.</p><p>{EVENT_DETAILS}</p><br/><p>Bei Fragen kontaktieren Sie uns gerne direkt.</p><p>Mit freundlichen Grüßen,<br/>Ihr Team der Flugschule Hirondelle</p>","bodyText":"Hallo {BOOKING_NAME}, Ihre Buchung für {EVENT_TITLE} wurde storniert. Ihre Buchung ist daher nicht mehr gültig. {EVENT_DETAILS}"}}' WHERE id = 'default';
